USE EnglishShadowingDB;
GO

SET XACT_ABORT ON;
GO

BEGIN TRANSACTION;

-- Replace the current Video Bank with the curated real-source list below.
-- The database stores YouTube source URLs and transcript JSON paths. Transcript
-- files are generated by tools/video-import/import_batch.py and must be reviewed
-- before changing source_review_status from pending to approved.

DECLARE @OldVideoBankLessons TABLE (lesson_id BIGINT PRIMARY KEY);
DECLARE @OldVideoBankSentences TABLE (sentence_id BIGINT PRIMARY KEY);

INSERT INTO @OldVideoBankLessons (lesson_id)
SELECT DISTINCT l.lesson_id
FROM Lessons AS l
INNER JOIN Courses AS c ON c.course_id = l.course_id
WHERE c.course_type = 'video_bank'
   OR c.title LIKE N'Video Bank%';

INSERT INTO @OldVideoBankSentences (sentence_id)
SELECT sentence_id
FROM Lesson_Sentences
WHERE lesson_id IN (SELECT lesson_id FROM @OldVideoBankLessons);

IF OBJECT_ID(N'dbo.Practice_Attempts', N'U') IS NOT NULL
BEGIN
    IF OBJECT_ID(N'dbo.Gamification_Ledger', N'U') IS NOT NULL
        DELETE FROM Gamification_Ledger
        WHERE attempt_id IN (
            SELECT attempt_id
            FROM Practice_Attempts
            WHERE sentence_id IN (SELECT sentence_id FROM @OldVideoBankSentences)
        );

    DELETE FROM Practice_Attempts
    WHERE sentence_id IN (SELECT sentence_id FROM @OldVideoBankSentences);
END

IF OBJECT_ID(N'dbo.Favorite_Sentences', N'U') IS NOT NULL
    DELETE FROM Favorite_Sentences
    WHERE sentence_id IN (SELECT sentence_id FROM @OldVideoBankSentences);

IF OBJECT_ID(N'dbo.Vocabulary_Items', N'U') IS NOT NULL
    DELETE FROM Vocabulary_Items
    WHERE source_sentence_id IN (SELECT sentence_id FROM @OldVideoBankSentences);

IF OBJECT_ID(N'dbo.Word_Error_Statistics', N'U') IS NOT NULL
    UPDATE Word_Error_Statistics
    SET last_sentence_id = NULL
    WHERE last_sentence_id IN (SELECT sentence_id FROM @OldVideoBankSentences);

IF OBJECT_ID(N'dbo.User_Sentence_Progress', N'U') IS NOT NULL
    DELETE FROM User_Sentence_Progress
    WHERE sentence_id IN (SELECT sentence_id FROM @OldVideoBankSentences);

IF OBJECT_ID(N'dbo.User_Lesson_Progress', N'U') IS NOT NULL
    DELETE FROM User_Lesson_Progress
    WHERE lesson_id IN (SELECT lesson_id FROM @OldVideoBankLessons);

IF OBJECT_ID(N'dbo.Practice_Sessions', N'U') IS NOT NULL
    DELETE FROM Practice_Sessions
    WHERE lesson_id IN (SELECT lesson_id FROM @OldVideoBankLessons);

DELETE FROM Lesson_Material
WHERE lesson_id IN (SELECT lesson_id FROM @OldVideoBankLessons);

DELETE FROM Lesson_Sentences
WHERE lesson_id IN (SELECT lesson_id FROM @OldVideoBankLessons);

DELETE FROM Lessons
WHERE lesson_id IN (SELECT lesson_id FROM @OldVideoBankLessons);

DELETE c
FROM Courses AS c
WHERE (c.course_type = 'video_bank' OR c.title LIKE N'Video Bank%')
  AND NOT EXISTS (SELECT 1 FROM Lessons AS l WHERE l.course_id = c.course_id);

