DECLARE
    @ImportMode VARCHAR(20),
    @ImportCourseTitle NVARCHAR(255),
    @ImportCourseLevel VARCHAR(20),
    @ImportCourseDescription NVARCHAR(MAX),
    @ImportLessonOrder INT,
    @ImportTitle NVARCHAR(255),
    @ImportDescription NVARCHAR(MAX),
    @ImportDuration INT,
    @ImportVideoUrl NVARCHAR(MAX),
    @ImportSourceId NVARCHAR(255),
    @ImportTranscriptUrl NVARCHAR(MAX),
    @ImportCourseId BIGINT,
    @ImportLessonId BIGINT;

DECLARE VideoBankImportCursor CURSOR LOCAL FAST_FORWARD FOR
SELECT learning_mode, course_title, course_level, course_description, lesson_order, title, description, duration, video_url, source_id, transcript_url
FROM @VideoBankImports
ORDER BY learning_mode, lesson_order;

OPEN VideoBankImportCursor;
FETCH NEXT FROM VideoBankImportCursor INTO
    @ImportMode, @ImportCourseTitle, @ImportCourseLevel, @ImportCourseDescription,
    @ImportLessonOrder, @ImportTitle, @ImportDescription, @ImportDuration,
    @ImportVideoUrl, @ImportSourceId, @ImportTranscriptUrl;

WHILE @@FETCH_STATUS = 0
BEGIN
    SET @ImportCourseId = NULL;
    SET @ImportLessonId = NULL;

    IF NOT EXISTS (SELECT 1 FROM Courses WHERE title = @ImportCourseTitle AND learning_mode = @ImportMode)
    BEGIN
        INSERT INTO Courses (title, [description], level, learning_mode, course_type)
        VALUES (@ImportCourseTitle, @ImportCourseDescription, @ImportCourseLevel, @ImportMode, 'video_bank');
        SET @ImportCourseId = SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        SELECT @ImportCourseId = course_id
        FROM Courses
        WHERE title = @ImportCourseTitle AND learning_mode = @ImportMode;

        UPDATE Courses
        SET [description] = @ImportCourseDescription,
            level = @ImportCourseLevel,
            course_type = 'video_bank'
        WHERE course_id = @ImportCourseId;
    END

    INSERT INTO Lessons (course_id, title, [description], lesson_order, duration)
    VALUES (@ImportCourseId, @ImportTitle, @ImportDescription, @ImportLessonOrder, @ImportDuration);
    SET @ImportLessonId = SCOPE_IDENTITY();

    INSERT INTO Lesson_Material
        (lesson_id, material_type, content_url, source_provider, source_id, license_note, source_review_status)
    VALUES
        (@ImportLessonId, 'video', @ImportVideoUrl, N'youtube', @ImportSourceId, N'Real video source. Review source ownership/license before public classroom use.', 'pending'),
        (@ImportLessonId, 'transcript', @ImportTranscriptUrl, N'youtube', @ImportSourceId, N'Manual captions imported with yt-dlp when available. Review caption quality before approving.', 'pending');

    FETCH NEXT FROM VideoBankImportCursor INTO
        @ImportMode, @ImportCourseTitle, @ImportCourseLevel, @ImportCourseDescription,
        @ImportLessonOrder, @ImportTitle, @ImportDescription, @ImportDuration,
        @ImportVideoUrl, @ImportSourceId, @ImportTranscriptUrl;
END

CLOSE VideoBankImportCursor;
DEALLOCATE VideoBankImportCursor;

-- Replace broken/duplicate curriculum seeds with the real grade 6-9 audio lessons.
DECLARE @OldCurriculumLessons TABLE (lesson_id BIGINT PRIMARY KEY);
DECLARE @OldCurriculumSentences TABLE (sentence_id BIGINT PRIMARY KEY);

INSERT INTO @OldCurriculumLessons (lesson_id)
SELECT DISTINCT l.lesson_id
FROM Lessons AS l
INNER JOIN Courses AS c ON c.course_id = l.course_id
LEFT JOIN Lesson_Material AS lm ON lm.lesson_id = l.lesson_id
WHERE c.course_type = 'curriculum'
   OR c.title LIKE N'Tiếng Anh lớp%'
   OR lm.content_url LIKE '/media/curriculum/%';

INSERT INTO @OldCurriculumSentences (sentence_id)
SELECT sentence_id
FROM Lesson_Sentences
WHERE lesson_id IN (SELECT lesson_id FROM @OldCurriculumLessons);

IF OBJECT_ID(N'dbo.Practice_Attempts', N'U') IS NOT NULL
BEGIN
    IF OBJECT_ID(N'dbo.Gamification_Ledger', N'U') IS NOT NULL
        DELETE FROM Gamification_Ledger
        WHERE attempt_id IN (
            SELECT attempt_id
            FROM Practice_Attempts
            WHERE sentence_id IN (SELECT sentence_id FROM @OldCurriculumSentences)
        );

    DELETE FROM Practice_Attempts
    WHERE sentence_id IN (SELECT sentence_id FROM @OldCurriculumSentences);
END

IF OBJECT_ID(N'dbo.Favorite_Sentences', N'U') IS NOT NULL
    DELETE FROM Favorite_Sentences
    WHERE sentence_id IN (SELECT sentence_id FROM @OldCurriculumSentences);

IF OBJECT_ID(N'dbo.Vocabulary_Items', N'U') IS NOT NULL
    DELETE FROM Vocabulary_Items
    WHERE source_sentence_id IN (SELECT sentence_id FROM @OldCurriculumSentences);

IF OBJECT_ID(N'dbo.Word_Error_Statistics', N'U') IS NOT NULL
    UPDATE Word_Error_Statistics
    SET last_sentence_id = NULL
    WHERE last_sentence_id IN (SELECT sentence_id FROM @OldCurriculumSentences);

IF OBJECT_ID(N'dbo.User_Sentence_Progress', N'U') IS NOT NULL
    DELETE FROM User_Sentence_Progress
    WHERE sentence_id IN (SELECT sentence_id FROM @OldCurriculumSentences);

IF OBJECT_ID(N'dbo.User_Lesson_Progress', N'U') IS NOT NULL
    DELETE FROM User_Lesson_Progress
    WHERE lesson_id IN (SELECT lesson_id FROM @OldCurriculumLessons);

IF OBJECT_ID(N'dbo.Practice_Sessions', N'U') IS NOT NULL
    DELETE FROM Practice_Sessions
    WHERE lesson_id IN (SELECT lesson_id FROM @OldCurriculumLessons);

IF OBJECT_ID(N'dbo.AI_Dialogue_Turns', N'U') IS NOT NULL
    DELETE FROM AI_Dialogue_Turns
    WHERE dialogue_session_id IN (
        SELECT dialogue_session_id
        FROM AI_Dialogue_Sessions
        WHERE lesson_id IN (SELECT lesson_id FROM @OldCurriculumLessons)
    );

IF OBJECT_ID(N'dbo.AI_Dialogue_Sessions', N'U') IS NOT NULL
    DELETE FROM AI_Dialogue_Sessions
    WHERE lesson_id IN (SELECT lesson_id FROM @OldCurriculumLessons);

DELETE FROM Lesson_Material
WHERE lesson_id IN (SELECT lesson_id FROM @OldCurriculumLessons);

DELETE FROM Lesson_Sentences
WHERE lesson_id IN (SELECT lesson_id FROM @OldCurriculumLessons);

DELETE FROM Lessons
WHERE lesson_id IN (SELECT lesson_id FROM @OldCurriculumLessons);

DELETE FROM Users_Courses
WHERE course_id IN (
    SELECT course_id
    FROM Courses
    WHERE course_type = 'curriculum'
       OR title LIKE N'Tiếng Anh lớp%'
);

DELETE FROM Courses
WHERE course_type = 'curriculum'
   OR title LIKE N'Tiếng Anh lớp%';

DECLARE @CurriculumImports TABLE
(
    course_title NVARCHAR(255) NOT NULL,
