    title NVARCHAR(255) NOT NULL,
    description NVARCHAR(MAX) NULL,
    duration INT NOT NULL,
    transcript_url NVARCHAR(MAX) NOT NULL,
    audio_url NVARCHAR(MAX) NOT NULL
