DECLARE
    @CurriculumCourseTitle NVARCHAR(255),
    @CurriculumCourseLevel VARCHAR(20),
    @CurriculumCourseDescription NVARCHAR(MAX),
    @CurriculumLessonOrder INT,
    @CurriculumTitle NVARCHAR(255),
    @CurriculumDescription NVARCHAR(MAX),
    @CurriculumDuration INT,
    @CurriculumTranscriptUrl NVARCHAR(MAX),
    @CurriculumAudioUrl NVARCHAR(MAX),
    @CurriculumCourseId BIGINT,
    @CurriculumLessonId BIGINT,
    @CurriculumSourceId NVARCHAR(255);

DECLARE CurriculumImportCursor CURSOR LOCAL FAST_FORWARD FOR
SELECT course_title, course_level, course_description, lesson_order, title, description, duration, transcript_url, audio_url
FROM @CurriculumImports
ORDER BY course_title, lesson_order;

OPEN CurriculumImportCursor;
FETCH NEXT FROM CurriculumImportCursor INTO
    @CurriculumCourseTitle, @CurriculumCourseLevel, @CurriculumCourseDescription,
    @CurriculumLessonOrder, @CurriculumTitle, @CurriculumDescription, @CurriculumDuration,
    @CurriculumTranscriptUrl, @CurriculumAudioUrl;

WHILE @@FETCH_STATUS = 0
BEGIN
    SET @CurriculumCourseId = NULL;
    SET @CurriculumLessonId = NULL;
    SET @CurriculumSourceId = REPLACE(REPLACE(@CurriculumTranscriptUrl, N'/media/curriculum/', N''), N'/transcript.json', N'');

    IF NOT EXISTS (SELECT 1 FROM Courses WHERE title = @CurriculumCourseTitle AND course_type = 'curriculum')
    BEGIN
        INSERT INTO Courses (title, [description], level, learning_mode, course_type)
        VALUES (@CurriculumCourseTitle, @CurriculumCourseDescription, @CurriculumCourseLevel, 'academic', 'curriculum');
        SET @CurriculumCourseId = SCOPE_IDENTITY();
    END
    ELSE
    BEGIN
        SELECT @CurriculumCourseId = course_id
        FROM Courses
        WHERE title = @CurriculumCourseTitle AND course_type = 'curriculum';
    END

    INSERT INTO Lessons (course_id, title, [description], lesson_order, duration)
    VALUES (@CurriculumCourseId, @CurriculumTitle, @CurriculumDescription, @CurriculumLessonOrder, @CurriculumDuration);
    SET @CurriculumLessonId = SCOPE_IDENTITY();

    INSERT INTO Lesson_Material
        (lesson_id, material_type, content_url, source_provider, source_id, license_note, source_review_status)
    VALUES
        (@CurriculumLessonId, 'transcript', @CurriculumTranscriptUrl, N'curriculum', @CurriculumSourceId, N'Curriculum transcript stored in repository media folder.', 'approved'),
        (@CurriculumLessonId, 'audio', @CurriculumAudioUrl, N'curriculum', @CurriculumSourceId, N'Curriculum audio stored in repository media folder.', 'approved');

    FETCH NEXT FROM CurriculumImportCursor INTO
        @CurriculumCourseTitle, @CurriculumCourseLevel, @CurriculumCourseDescription,
        @CurriculumLessonOrder, @CurriculumTitle, @CurriculumDescription, @CurriculumDuration,
        @CurriculumTranscriptUrl, @CurriculumAudioUrl;
END

CLOSE CurriculumImportCursor;
DEALLOCATE CurriculumImportCursor;

COMMIT TRANSACTION;
